package com.wattscape.room;
import com.wattscape.audit.AuditEvent; import com.wattscape.audit.AuditEventRepository; import com.wattscape.building.BuildingRepository; import com.wattscape.common.ApiException; import com.wattscape.floor.FloorRepository; import com.wattscape.identity.TenantContext; import com.wattscape.site.SiteService; import com.wattscape.twin.TwinEdge; import com.wattscape.twin.TwinEdgeRepository; import com.wattscape.twin.TwinNode; import com.wattscape.twin.TwinNodeRepository; import org.slf4j.MDC; import org.springframework.security.core.Authentication; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.List; import java.util.UUID;
@Service public class RoomService {
 private final RoomRepository rooms; private final SiteService sites; private final TenantContext tenant; private final FloorRepository floors; private final BuildingRepository buildings; private final AuditEventRepository audit; private final TwinNodeRepository nodes; private final TwinEdgeRepository edges;
 public RoomService(RoomRepository r,SiteService s,TenantContext t,FloorRepository f,BuildingRepository b,AuditEventRepository a,TwinNodeRepository n,TwinEdgeRepository e){rooms=r;sites=s;tenant=t;floors=f;buildings=b;audit=a;nodes=n;edges=e;}
 @Transactional(readOnly=true) public List<RoomDtos.RoomResponse> list(UUID siteId,Authentication auth){var site=sites.requireSite(siteId,auth);return rooms.findAllBySiteIdAndOrganizationIdOrderByCode(siteId,site.getOrganizationId()).stream().map(RoomDtos.RoomResponse::from).toList();}
 @Transactional public RoomDtos.RoomResponse create(UUID siteId,RoomDtos.CreateRoomRequest req,Authentication auth){var member=tenant.requireRole(auth,"Organization Owner","Organization Admin","Site Admin","Facilities Operator");var site=sites.requireSite(siteId,auth);var floor=floors.findByIdAndOrganizationId(req.floorId(),site.getOrganizationId()).orElseThrow(()->ApiException.badRequest("Floor does not belong to this site"));if(buildings.findByIdAndOrganizationIdAndSiteId(floor.getBuildingId(),site.getOrganizationId(),siteId).isEmpty())throw ApiException.badRequest("Floor does not belong to this site");Room r=rooms.save(new Room(site.getOrganizationId(),siteId,req.floorId(),req.code().trim(),req.name().trim(),req.zoneType(),req.areaSqm()));TwinNode roomNode=nodes.save(new TwinNode(site.getOrganizationId(),siteId,"space",r.getName(),"room:"+r.getId()));TwinNode floorNode=nodes.findAllBySiteIdAndOrganizationIdOrderByKindAscNameAsc(siteId,site.getOrganizationId()).stream().filter(n->n.getKind().equals("floor")&&n.getSourceId().equals("floor:"+req.floorId())).findFirst().orElseThrow(()->ApiException.conflict("Twin floor node is not provisioned"));edges.save(new TwinEdge(site.getOrganizationId(),floorNode.getId(),roomNode.getId(),"contains"));audit.save(new AuditEvent(site.getOrganizationId(),member.getSubject(),"ROOM_CREATED","room",r.getId(),"allowed",MDC.get("requestId"),java.util.Map.of()));return RoomDtos.RoomResponse.from(r);}
}
